#ifndef SENSOR_4_20MA
#define SENSOR_4_20MA

/**
 * @file Sensor_4_20mA.h
 * @brief 4-20mA current loop sensor interface for Industruino IND.I/O.
 * 
 * Provides periodic analog current reading and out-of-range fault detection
 * (e.g. broken loop wire < 3.8mA or overcurrent > 21.0mA).
 */

class Sensor_4_20mA {
public:
    /**
     * @brief Events generated by the sensor update cycle.
     */
    enum Event {
        None          = 0,      ///< No new sample acquired (sampling interval not reached).
        NewSample     = 1 << 0, ///< A new valid current sample was measured within normal range.
        OutOfRange    = 1 << 1  ///< Measurement is outside normal 4-20mA range (wire break or fault).
    };

    /**
     * @brief Construct a new 4-20mA sensor instance.
     * 
     * @param channel Industruino analog input channel number (1 to 4).
     */
    Sensor_4_20mA(int channel);

    /**
     * @brief Default destructor.
     */
    ~Sensor_4_20mA() = default;

    /**
     * @brief Initialize the hardware channel and set sampling interval.
     * 
     * Sets the analog channel mode to mA reading on the Industruino IND.I/O board
     * and performs an initial reading.
     * 
     * @param samplingPeriod Minimum time in milliseconds between successive readings.
     */
    void begin(unsigned long samplingPeriod);

    /**
     * @brief Retrieve the most recent current measurement.
     * 
     * @return float Last measured current in milliamperes (mA).
     */
    float read();

    /**
     * @brief Check sampling timer, read hardware ADC if due, and validate limits.
     * 
     * @param now Current system time in milliseconds.
     * @return Event Event::NewSample if valid, Event::OutOfRange if faulty, or Event::None if not due.
     */
    Event update(unsigned long now);

private:
    int _channel;                    ///< Industruino analog input channel index.
    unsigned long _samplingPeriod;   ///< Sampling period interval in milliseconds.
    unsigned long _lastSensorReading;///< System timestamp (ms) of the last completed sample.
    float _last_sample;              ///< Cached current reading in mA.
    unsigned _errors;                ///< Cumulative error counter.
};

#endif // SENSOR_4_20MA
